export default function HPPComparison(){
 const theme=useHostTheme(); const [ct,setCt]=useState("8"),[py,setPy]=useState("12"),[pf,setPf]=useState("5"),[cf,setCf]=useState("3"),[mo,setMo]=useState("12");
 const C=11.88,P=14.46,D=1.1875,t=Math.max(.01,Number(mo)/12),f=Math.max(0,Number(pf)/100),g=Math.max(0,Number(cf)/100),target=Math.max(0,Number(ct)),y=Math.max(.001,Number(py)/100);
 const cr=1-target/C-g*t,pr=1-D/y/P-D*t/P-f*t,match=P*(1-cr-f*t)-D*t;const pct=(v:number)=>(v*100).toFixed(1)+"%";
 const yields=[7,8.21,10,12,14,16,18,20];
 return <Stack gap={14} style={{padding:24,color:theme.text.primary,background:theme.bg.editor}}>
 <H1>HPP callable 与普通股：下跌空间</H1>
 <Text tone="secondary">研究日 2026-10-09；共同价格截点 2026-10-08。所有退出价与借券费为无概率情景，收益按初始名义金额。</Text>
 <Text weight="semibold">目前无法证明 Series C 的可实现空头收益更大。普通股先吸收资产损失；优先股需更强收益率／信用重估并覆盖股息补偿。</Text>
 <Table headers={["证券","收盘价","年股息／股","重要条款"]} rows={[["HPP 普通股","$11.88","$0（模型假设）","每股 NAV／稀释待核对"],["Series C","$14.46","$1.1875","永续累计；$25 清算优先；2026-11-16 起可选赎回"]]}/>
 <H2>持仓情景</H2><Row wrap gap={15}>{[["普通股退出价 $",ct,setCt],["优先股要求收益率 %",py,setPy],["普通股年借券费 %",cf,setCf],["优先股年借券费 %",pf,setPf],["持有月数",mo,setMo]].map(([label,value,setter])=><Stack key={String(label)} gap={4} style={{width:180}}><Text size="small">{String(label)}</Text><TextInput type="number" value={String(value)} onChange={setter as (s:string)=>void}/></Stack>)}</Row>
 <Table headers={["普通股净情景收益","优先股净情景收益","优先股需低于此价才能超过普通股"]} rows={[[pct(cr),pct(pr),match>0?"$"+match.toFixed(2)+" / 要求收益率 "+pct(D/match):"持续派息成本下无法超过"]]}/>
 <H2>要求收益率与净空头收益</H2><Text size="small" tone="secondary">横轴：要求收益率 %；纵轴：净空头收益／初始金额 %。持续派息、无赎回；固定初始名义金额借券费。</Text>
 <LineChart categories={yields.map(v=>v+"%")} series={[{name:"Series C 净情景收益",data:yields.map(v=>(1-D/(v/100)/P-D*t/P-f*t)*100),tone:"info"},{name:"HPP 普通股净情景收益",data:yields.map(()=>cr*100),tone:"neutral"}]} height={290} valueSuffix="%" beginAtZero={false}/>
 <Text size="small" tone="secondary">来源：2026-10-08 行情与发行人条款，模型变换。未计实时借券、返利、税费、回补风险。D/y 在停息和欠息时不适用。</Text>
 <Divider/><H2>一年基准比较</H2><Text>普通股降至 $8、借券费 3%：净收益 29.7%。Series C 借券费 5%且持续派息，需要低于 $8.26、要求收益率约 14.38%才能匹配。12%收益率情景净赚18.4%；16%情景净赚35.5%。这些不是联合经济状态或概率预测。</Text>
 <H2>清算条件分配（不是当前 NAV）</H2><Text size="small">已扣所有更高级索偿；假设 1,700 万股不变、无欠息或其它同级优先股。低于 $425m 时普通股无清算回收。交易价格可以提前变化。</Text>
 <Table headers={["可分配池 $m","Series C 回收／股","普通股剩余 $m"]} rows={DATA.liquidation_pool_scenarios.map(r=>[r.available_after_all_senior_claims_m.toFixed(2),"$"+r.preferred_recovery_per_share.toFixed(2),r.common_residual_m.toFixed(2)])}/>
 <H2>推进状态</H2><Text>已复现旧面板和 63 项测试，新增 13 项测试及 456 个成本情景。债券 tender 未确认结算，债务扣减零；$98／$99.125 是发行人回购报价，不能冒充债券市场成交价。下一步核对现金／净债务、已售物业 NOI、2027–2030 融资与租赁资本开支。</Text>
 <Text>以 $25 赎回对应当前优先股空头约 72.9% 价格损失。首次可赎回日期不等于强制赎回；借券可用性与费率仍未知。</Text>
 <H2>来源</H2>{DATA.facts.sources.map(s=><Text key={s.id} size="small"><Link href={s.url}>{s.id}</Link> — {"locator" in s?s.locator:"published_at" in s?s.published_at:""}</Text>)}
 </Stack>
}